// Interactive Bible Games — question banks, daily rotation and endless practice.
//
// The banks live in ./games/*.json and are generated by scripts/gen_games.py from the bundled KJV
// text (src/data/kjv_bible.json), book metadata and a hand-curated set (scripts/games_curated.py).
// Every question cites a KJV reference. Validate with scripts/validate_games.py after regenerating.
//
// • Daily: players get a fresh, date-seeded set every day (see ./games/daily.js); coins are only
//   awarded for the first round of each game per day (enforced by the server in online mode).
// • Practice ("Keep playing"): after the daily set, an endless stream drawn from the WHOLE bank
//   (≥ 1,500 items per game) with no repeats until the bank is exhausted, then reshuffled. No coins.
//
// Banks are loaded lazily (first time a game is opened) so ~2 MB of JSON isn't parsed at app start.
import META from './games/meta.json';
import { dailySelection, dateKey, hash, shuffled, rng, resetLabel, msUntilReset, shuffleOptions, createEndless, newSeed } from './games/daily';

export { dateKey, resetLabel, msUntilReset, newSeed };

export const GAME_CATEGORIES = [
  { id: 'all', label: 'All Challenges' },
  { id: 'gospels', label: 'Gospels & Jesus' },
  { id: 'old_testament', label: 'Old Testament' },
  { id: 'miracles', label: 'Miracles & Parables' },
  { id: 'prophets', label: 'Prophets & Kings' },
  { id: 'acts', label: 'Acts & Apostles' },
  { id: 'books', label: 'Books of the Bible' },
  { id: 'verses', label: 'Know the verse' },
];
const CAT_LABEL = Object.fromEntries(GAME_CATEGORIES.map((c) => [c.id, c.label]));

// ---------- Banks in the shape the screens use ----------
const toChoice = (x, label) => ({
  id: x.id,
  pool: x.k,
  category: x.c,
  categoryLabel: label || CAT_LABEL[x.c] || 'Bible trivia',
  question: x.q,
  options: x.o,
  correctIndex: x.a,
  reference: x.r,
  explanation: x.x,
});

/* eslint-disable global-require */
const BUILD = {
  trivia: () => require('./games/trivia.json').map((x) => toChoice(x)),
  who: () => require('./games/who.json').map((x) => ({ ...toChoice(x, 'Who said it?'), quote: `“${x.q}”`, question: `“${x.q}”` })),
  scramble: () => require('./games/scramble.json').map((x) => ({
    id: x.id,
    pool: x.k,
    reference: x.r,
    correctOrder: x.w,
    scrambledWords: x.w, // re-shuffled per day by scrambleFor()
    verseText: x.x,
  })),
  chronology: () => require('./games/chronology.json').map((x) => toChoice(x, x.k === 'books' ? 'Order of the books' : 'Bible timeline')),
};
/* eslint-enable global-require */
const banks = {};
export function gameBank(gameId) {
  const id = BUILD[gameId] ? gameId : 'trivia';
  if (!banks[id]) banks[id] = BUILD[id]();
  return banks[id];
}

// Canonical game ids (shared by Discover and Learn so stats line up)
export const GAME_IDS = ['trivia', 'who', 'scramble', 'chronology'];
export const GAME_COUNTS = { ...META };
// GAME_BANKS.trivia etc. still work (loaded on first access).
export const GAME_BANKS = {};
GAME_IDS.forEach((id) => Object.defineProperty(GAME_BANKS, id, { enumerable: true, get: () => gameBank(id) }));

// How many of each pool go into one day's session
export const DAILY_MIX = {
  trivia: [['story', 6], ['verse', 4], ['books', 2]],
  who: [['famous', 4], ['more', 8]],
  scramble: [['famous', 4], ['more', 4]],
  chronology: [['events', 7], ['books', 5]],
};
export const DAILY_SIZE = Object.fromEntries(Object.entries(DAILY_MIX).map(([g, m]) => [g, m.reduce((n, [, c]) => n + c, 0)]));
export const GAME_TITLES = { trivia: 'Bible trivia', who: 'Who said it?', scramble: 'Verse scramble', chronology: 'Bible timeline' };

// Shuffle a verse's words for the day (never returns the correct order)
function scrambleFor(v, seed) {
  let w = shuffled(v.correctOrder, seed);
  if (w.join(' ') === v.correctOrder.join(' ')) w = w.slice(1).concat(w.slice(0, 1));
  return { ...v, scrambledWords: w };
}

// Turn a scramble round into a 4-choice question ("pick the correct order") for quick play.
export function scrambleAsChoice(v, seed = hash(v.id)) {
  const right = v.correctOrder.join(' ');
  const r = rng(seed);
  const n = v.correctOrder.length;
  const variants = new Set();
  let guard = 0;
  while (variants.size < 3 && guard < 60) {
    guard += 1;
    const a = v.correctOrder.slice();
    const kind = guard % 3;
    if (kind === 0) { const i = Math.floor(r() * (n - 1)); [a[i], a[i + 1]] = [a[i + 1], a[i]]; }
    else if (kind === 1) { const i = Math.floor(r() * n); let j = Math.floor(r() * n); if (j === i) j = (i + 2) % n; [a[i], a[j]] = [a[j], a[i]]; }
    else { const k = 1 + Math.floor(r() * (n - 1)); a.push(...a.splice(0, k)); }
    const s = a.join(' ');
    if (s !== right) variants.add(s);
  }
  const options = shuffled([right, ...Array.from(variants).slice(0, 3)], seed ^ 0x9e3779b9);
  return {
    id: v.id,
    categoryLabel: 'Verse scramble',
    question: `Which is the correct order of ${v.reference}?`,
    options,
    correctIndex: options.indexOf(right),
    reference: v.reference,
    explanation: v.verseText,
  };
}

// Today's questions for a game (deterministic for the local date).
export function dailyQuestions(gameId, date = new Date()) {
  const bank = gameBank(gameId);
  const mix = DAILY_MIX[gameId] || DAILY_MIX.trivia;
  if (gameId === 'scramble') {
    const day = dateKey(date);
    return dailySelection('scramble', bank, mix, date, { shuffleChoices: false }).map((v) => scrambleFor(v, hash(`${v.id}@${day}`)));
  }
  return dailySelection(gameId, bank, mix, date);
}

// ---------- Endless practice ("Keep playing") ----------
// practiceSession(gameId, { seed, start }) -> { next(), position, size }
//   next() returns the next question (options / words shuffled for this lap), never one from today's
//   daily set, with no repeats until the whole bank has been served. Save { seed, position } to resume.
export function practiceSession(gameId, { seed = newSeed(), start = 0, date = new Date() } = {}) {
  const bank = gameBank(gameId);
  const exclude = dailyQuestions(gameId, date).map((q) => q.id);
  const it = createEndless(bank, { seed, start, exclude });
  return {
    seed,
    next() {
      const r = it.next();
      if (!r) return null;
      const salt = hash(`${r.item.id}#practice${seed}:${r.lap}`);
      return gameId === 'scramble' ? scrambleFor(r.item, salt) : shuffleOptions(r.item, salt);
    },
    get position() { return it.position; },
    get size() { return it.size; },
  };
}

